import React from "react";
import { Link } from "react-router-dom";

function Sidebar() {
  return (
    <div style={styles.sidebar}>
      <h2>🛡 SOC Panel</h2>

      <ul style={styles.menu}>
        <li><Link to="/" style={styles.link}>Dashboard</Link></li>
        <li><Link to="/threats" style={styles.link}>Threats</Link></li>
        <li><Link to="/incidents" style={styles.link}>Incidents</Link></li>
        <li><Link to="/packets" style={styles.link}>Packets</Link></li>
        <li><Link to="/settings" style={styles.link}>Settings</Link></li>
      </ul>
    </div>
  );
}

const styles = {
  sidebar: {
    width: "240px",
    background: "#111827",
    padding: "20px",
    minHeight: "100vh"
  },
  menu: {
    listStyle: "none",
    padding: 0,
    marginTop: "30px",
    lineHeight: "45px",
    fontSize: "18px"
  },
  link: {
    color: "white",
    textDecoration: "none",
    display: "block"
  }
};

export default Sidebar;
